#[contractimpl]
pub struct GovernorSimple;

#[contractimpl]
impl GovernorSimple {
    pub fn create_proposal(env: Env, proposer: Address, description: String) -> u64 {
        let proposal_id = env.storage().instance()
            .get::<_, u64>(&symbol_short!("next_proposal_id"))
            .unwrap_or(1);

        let mut proposals: Map<u64, (String, i128, i128, u64)> = env.storage().instance()
            .get(&symbol_short!("proposals"))
            .unwrap_or_else(|| Map::new(&env));

        proposals.set(proposal_id, (description, 0, 0, env.ledger().sequence()));
        env.storage().instance().set(&symbol_short!("proposals"), &proposals);
        env.storage().instance().set(&symbol_short!("next_proposal_id"), &(proposal_id + 1));

        proposal_id
    }

    pub fn vote(env: Env, proposal_id: u64, voter: Address, support: bool) -> bool {
        let mut proposals: Map<u64, (String, i128, i128, u64)> = env.storage().instance()
            .get(&symbol_short!("proposals"))
            .unwrap_or_else(|| Map::new(&env));

        if let Some((desc, yes_votes, no_votes, created_at)) = proposals.get(proposal_id) {
            let (new_yes, new_no) = if support {
                (yes_votes + 1, no_votes)
            } else {
                (yes_votes, no_votes + 1)
            };
            proposals.set(proposal_id, (desc, new_yes, new_no, created_at));
            env.storage().instance().set(&symbol_short!("proposals"), &proposals);
            return true;
        }
        false
    }
}
