#[contractimpl]
pub struct ReentrancyGuard;

#[contractimpl]
impl ReentrancyGuard {
    const LOCKED: u32 = 1;
    const UNLOCKED: u32 = 0;

    pub fn withdraw(env: Env, amount: i128) -> bool {
        let locked: u32 = env.storage().instance()
            .get(&symbol_short!("locked"))
            .unwrap_or(0);

        if locked == Self::LOCKED {
            return false;
        }

        env.storage().instance().set(&symbol_short!("locked"), &Self::LOCKED);

        // Perform the withdrawal
        let balance: i128 = env.storage().instance()
            .get(&symbol_short!("balance"))
            .unwrap_or(0);

        if balance >= amount {
            env.storage().instance().set(&symbol_short!("balance"), &(balance - amount));
        }

        env.storage().instance().set(&symbol_short!("locked"), &Self::UNLOCKED);
        true
    }
}
```

