アクセス制御は、スマートコントラクトセキュリティの最も重要な要素です。

```rust
#[contractimpl]
pub struct AccessControlFix;

#[contractimpl]
impl AccessControlFix {
    pub fn protected_withdraw(env: Env, user: Address, amount: i128) -> bool {
        // Verify the caller is the user
        let caller = env.invoker();
        if caller != user {
            return false;
        }

        // Check balance
        let mut balances: Map<Address, i128> = env.storage().instance()
            .get(&symbol_short!("balances"))
            .unwrap_or_else(|| Map::new(&env));

        let balance = balances.get(user.clone()).unwrap_or(0);
        if balance < amount {
            return false;
        }

        // Update state before external interactions (CEI pattern)
        balances.set(user.clone(), balance - amount);
        env.storage().instance().set(&symbol_short!("balances"), &balances);

        // Emit event
        env.events().publish(
            (symbol_short!("withdraw"),),
            (user, amount),
        );

        true
    }
}
```
